import React from "react";
import {Button} from "@mui/material";
import {Link} from "react-router-dom";
export default function TaskLink({kind, id}: {kind: "order" | "product" | "document"; id?: string | number}) {
    return id ? <Button component={Link} to={`/collaboration?kind=${kind}&id=${encodeURIComponent(String(id))}&view=tasks`}>Поставить задачу</Button> : null;
}
