import TaskLink from "../collaboration/TaskLink";
import CompanyCard, {parseCompanySnapshot} from '../counterparties/CompanyCard';
import {
  Box,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
} from "@mui/material";
import React from "react";
import {Link as RouterLink, useParams} from "react-router-dom";
import styledCom from "styled-components";
import moment from "moment";
import {styled} from "@mui/material/styles";
import {
  EmptyState,
  MainDiv,
  PageHeader,
  PageSubtitle,
  PageTitle,
  PageTitleGroup,
  Surface,
} from "../../ui/commonStyled/commonStyled";
import Loader from "../../ui/loader/loader";
import {OrderItemType} from "../../models/order";
import {useGetOrderByIdQuery} from "./createOrder/createOrderApi";
import {useTranslation} from "../../i18n";

const OrderDetailsDiv = styledCom(Surface)({
  display: "grid",
  gap: "14px",
  marginBottom: "16px",
});

const DetailsGrid = styledCom.div({
  display: "grid",
  gridTemplateColumns: "repeat(3, minmax(0, 1fr))",
  gap: "12px",

  "@media (max-width: 980px)": {
    gridTemplateColumns: "repeat(2, minmax(0, 1fr))",
  },

  "@media (max-width: 640px)": {
    gridTemplateColumns: "1fr",
  },
});

const DetailItem = styledCom.div({
  display: "grid",
  gap: "4px",
  minWidth: 0,
  padding: "12px",
  backgroundColor: "var(--color-surface-soft)",
  border: "1px solid var(--color-border)",
  borderRadius: "12px",
});

const DetailLabel = styledCom.span({
  color: "var(--color-muted)",
  fontSize: "12px",
  fontWeight: 760,
  lineHeight: 1.2,
});

const DetailValue = styledCom.span({
  minWidth: 0,
  overflow: "hidden",
  color: "var(--color-text)",
  fontSize: "14px",
  fontWeight: 720,
  lineHeight: 1.45,
  textOverflow: "ellipsis",
});

const SummaryTitle = styledCom.div({
  padding: "14px 16px 2px",
  color: "var(--color-text)",
  fontSize: "16px",
  fontWeight: 780,
});

const SummaryNote = styledCom.div({
  padding: "0 16px 12px",
  color: "var(--color-muted)",
  fontSize: "13px",
  fontWeight: 560,
  lineHeight: 1.5,
});

const SummaryAmount = styledCom.span({
  color: "var(--color-text)",
  fontWeight: 780,
});

const SummaryTotalCell = styled(TableCell)({
  color: "var(--color-text)",
  fontWeight: 800,
});

const StyledImage = styledCom.img({
  height: 46,
  width: 46,
  marginRight: 12,
  objectFit: "cover",
  borderRadius: "10px",
  border: "1px solid var(--color-border)",
});

const ProductDetailsLink = styledCom(RouterLink)({
  display: "grid",
  gap: "2px",
  minWidth: 0,
  color: "var(--color-primary)",
  fontWeight: 720,
  textDecoration: "none",

  "&:hover": {
    textDecoration: "underline",
  },

  "&:focus-visible": {
    outline: "2px solid var(--color-primary)",
    outlineOffset: "3px",
    borderRadius: "4px",
  },
});

const ProductId = styledCom.span({
  color: "var(--color-muted)",
  fontSize: "12px",
  fontWeight: 650,
});

const StyledTableContainer = styled(TableContainer)({
  marginTop: "16px",
  border: "1px solid var(--color-border)",
  borderRadius: "16px",
  background: "var(--color-surface)",
  boxShadow: "var(--shadow-soft)",
});

const formatDate = (date: string) => moment(date).format("DD.MM.YYYY");

const formatMoney = (value: number | null | undefined, locale: string) =>
  `${(value ?? 0).toLocaleString(locale, {
    minimumFractionDigits: 0,
    maximumFractionDigits: 2,
  })} BYN`;

const formatPercent = (value: number | null | undefined, locale: string) =>
  `${(value ?? 0).toLocaleString(locale, {
    minimumFractionDigits: 0,
    maximumFractionDigits: 2,
  })} %`;

const getOrderItemName = (
  item: {itemName?: string; product?: string; name?: string},
  fallback: string,
) => item.itemName || item.product || item.name || fallback;

const OrderDetails = () => {
  const {id} = useParams<{ id: string }>();
  const {data: order, isLoading, isError} = useGetOrderByIdQuery(id!, {skip: !id});
  const {t, locale} = useTranslation();

  if (isLoading) {
    return <Loader/>;
  }

  const fallbackItemsSum = order?.orderItems.reduce((sum, item) => sum + (item.sum ?? 0), 0) ?? 0;
  const sumDetails = order
    ? {
      itemsSum: order.sumDetails?.itemsSum ?? fallbackItemsSum,
      deliverySum: order.sumDetails?.deliverySum ?? order.totalSum - fallbackItemsSum,
      currentDeliveryMethodPrice: order.sumDetails?.currentDeliveryMethodPrice,
      totalBeforeDiscount: order.sumDetails?.totalBeforeDiscount ?? order.totalSum,
      discountPercent: order.sumDetails?.discountPercent ?? order.discount ?? 0,
      discountAmount: order.sumDetails?.discountAmount ?? order.totalSum - order.finalSum,
      finalSum: order.sumDetails?.finalSum ?? order.finalSum,
    }
    : undefined;
  const hasCurrentDeliveryPriceDifference = Boolean(
    sumDetails?.currentDeliveryMethodPrice !== undefined &&
    Math.abs(sumDetails.deliverySum - sumDetails.currentDeliveryMethodPrice) >= 0.01,
  );

  return (
    <MainDiv>
      <PageHeader>
        <PageTitleGroup>
          <PageTitle>{order ? t("Заказ #{id}", {id: order.id}) : t("Детали заказа")}</PageTitle>
          <PageSubtitle>
            {t("Клиент, доставка, оплата и состав заказа из данных backend.")}
          </PageSubtitle>
        </PageTitleGroup>
      <TaskLink kind="order" id={order?.id}/>
      {order && <Button component={RouterLink} to={`/orderPipeline?order=${order.id}`}>Воронка и контроль</Button>}
</PageHeader>

      {order && !isError ? (
        <>
          <OrderDetailsDiv>
            <DetailsGrid>
              <DetailItem>
                <DetailLabel>{t("Создан")}</DetailLabel>
                <DetailValue>{formatDate(order.createdDate)}</DetailValue>
              </DetailItem>
              <DetailItem>
                <DetailLabel>{t("Обновлен")}</DetailLabel>
                <DetailValue>{formatDate(order.lastModifiedDate)}</DetailValue>
              </DetailItem>
              <DetailItem>
                <DetailLabel>{t("Статус")}</DetailLabel>
                <DetailValue>{order.status}</DetailValue>
              </DetailItem>
              <DetailItem>
                <DetailLabel>Ответственные</DetailLabel>
                <DetailValue>{order.responsibleUsers?.length ? order.responsibleUsers.map(user => user.name).join(", ") : order.responsibleUserName || "Не назначены"}</DetailValue>
              </DetailItem>
              <DetailItem>
                <DetailLabel>{t("Клиент")}</DetailLabel>
                <DetailValue>{order.customer.id ? <RouterLink to={`/customers?customer=${order.customer.id}`}>{order.customer.name}</RouterLink> : order.customer.name}</DetailValue>
              </DetailItem>
              <DetailItem>
                <DetailLabel>{t("Телефон")}</DetailLabel>
                <DetailValue>
                  <a href={`tel:${order.customer.phone}`}>{order.customer.phone}</a>
                </DetailValue>
              </DetailItem>
              <DetailItem>
                <DetailLabel>{t("Адрес")}</DetailLabel>
                <DetailValue>{order.customer.address}</DetailValue>
              </DetailItem>
              <DetailItem>
                <DetailLabel>{t("Доставка")}</DetailLabel>
                <DetailValue>{order.deliveryMethod}</DetailValue>
              </DetailItem>
              <DetailItem>
                <DetailLabel>{t("Источник")}</DetailLabel>
                <DetailValue>{order.source}</DetailValue>
              </DetailItem>
              <DetailItem>
                <DetailLabel>{t("Оплата")}</DetailLabel>
                <DetailValue>{order.paymentMethod}</DetailValue>
              </DetailItem>
              <DetailItem>
                <DetailLabel>{t("Комментарий")}</DetailLabel>
                <DetailValue>{order.comment || t("Нет комментария")}</DetailValue>
              </DetailItem>
            </DetailsGrid>
          </OrderDetailsDiv>

          <StyledTableContainer>
            {parseCompanySnapshot(order.counterpartyJson) && <Box sx={{p: 2}}><CompanyCard company={parseCompanySnapshot(order.counterpartyJson)!}/></Box>}
            <Table sx={{minWidth: 650}}>
              <TableHead>
                <TableRow>
                  <TableCell>{t("Позиция")}</TableCell>
                  <TableCell align="right">{t("Цена")}</TableCell>
                  <TableCell align="center">{t("Количество")}</TableCell>
                  <TableCell align="right">{t("Сумма")}</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {order.orderItems.map((item) => {
                  const itemName = getOrderItemName(item, t("Позиция"));
                  const productId = item.itemType === OrderItemType.Product
                    ? item.productId ?? item.id
                    : null;

                  return (
                    <TableRow
                      key={`${item.itemType}:${item.productId ?? item.serviceId ?? item.id}`}
                      sx={{"&:last-child td, &:last-child th": {border: 0}}}
                    >
                      <TableCell component="th" scope="row">
                        <Box display="flex" alignItems="center">
                          {item.imageName && <StyledImage src={item.imageName} alt={itemName}/>}
                          {productId !== null ? (
                            <ProductDetailsLink
                              to={`/productDetails/${productId}`}
                              state={{returnTo: `/ordersManagement/${id}`}}
                              aria-label={`${t("Подробнее")}: ${itemName}, ID ${productId}`}
                            >
                              <span>{itemName}</span>
                              <ProductId>ID: {productId}</ProductId>
                            </ProductDetailsLink>
                          ) : (
                            <span>{itemName}</span>
                          )}
                        </Box>
                      </TableCell>
                      <TableCell align="right">{formatMoney(item.price, locale)}</TableCell>
                      <TableCell align="center">{item.count}</TableCell>
                      <TableCell align="right">{formatMoney(item.sum, locale)}</TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </StyledTableContainer>

          <StyledTableContainer>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell colSpan={3}>
                    <SummaryTitle>{t("Разбивка суммы")}</SummaryTitle>
                    <SummaryNote>
                      {t("Показывает, из каких частей сложилась сохраненная сумма заказа.")}
                    </SummaryNote>
                  </TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                <TableRow>
                  <TableCell colSpan={2}>{t("Сумма позиций")}</TableCell>
                  <TableCell align="right">
                    <SummaryAmount>{formatMoney(sumDetails?.itemsSum, locale)}</SummaryAmount>
                  </TableCell>
                </TableRow>
                <TableRow>
                  <TableCell colSpan={2}>{t("Доставка: {method}", {method: order.deliveryMethod})}</TableCell>
                  <TableCell align="right">
                    <SummaryAmount>{formatMoney(sumDetails?.deliverySum, locale)}</SummaryAmount>
                  </TableCell>
                </TableRow>
                {hasCurrentDeliveryPriceDifference && (
                  <TableRow>
                    <TableCell colSpan={2}>{t("Текущий тариф этого способа доставки")}</TableCell>
                    <TableCell align="right">
                      {formatMoney(sumDetails?.currentDeliveryMethodPrice, locale)}
                    </TableCell>
                  </TableRow>
                )}
                <TableRow>
                  <TableCell colSpan={2}>{t("Итого до скидки")}</TableCell>
                  <TableCell align="right">
                    <SummaryAmount>{formatMoney(sumDetails?.totalBeforeDiscount, locale)}</SummaryAmount>
                  </TableCell>
                </TableRow>
                <TableRow>
                  <TableCell colSpan={2}>{t("Скидка, %")}</TableCell>
                  <TableCell align="right">{formatPercent(sumDetails?.discountPercent, locale)}</TableCell>
                </TableRow>
                <TableRow>
                  <TableCell colSpan={2}>{t("Скидка, BYN")}</TableCell>
                  <TableCell align="right">{formatMoney(sumDetails?.discountAmount, locale)}</TableCell>
                </TableRow>
                <TableRow>
                  <SummaryTotalCell colSpan={2}>{t("Финальная сумма")}</SummaryTotalCell>
                  <SummaryTotalCell align="right">
                    {formatMoney(sumDetails?.finalSum, locale)}
                  </SummaryTotalCell>
                </TableRow>
              </TableBody>
            </Table>
          </StyledTableContainer>
        </>
      ) : (
        <EmptyState>
          <strong>{t("Заказ не загружен")}</strong>
          <span>{t("Проверьте ID заказа или попробуйте позже.")}</span>
        </EmptyState>
      )}
    </MainDiv>
  );
};

export default OrderDetails;
